    private function get_candidate_verify_url($user_id, $token, $login = '', $key = '') {
        $args = [
            'view' => 'candidate-verify',
            'uid' => (int) $user_id,
            'token' => rawurlencode($token),
        ];
        if ($login !== '' && $key !== '') {
            $args['login'] = rawurlencode($login);
