    private function normalize_staff_lounge_thread_type($thread_type = '') {
        $thread_type = sanitize_key((string) $thread_type);
        if (in_array($thread_type, ['staff_lounge', 'stafflounge', 'internal_chat', 'internal', 'messages', 'chat'], true)) {
            return 'staff_lounge';
        }
