        <?php
        $inner = ob_get_clean();
        return $this->render_staff_shell('staff', $inner);
    }

    public function render_staff_settings_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        if (!$this->is_staff_user()) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>Settings are available to staff only.</p></div></section>';
        }
        $can_manage_admin_tools = $this->is_admin_user();
        $portal_page = get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $candidate_preview = add_query_arg(['as' => 'candidate'], $portal_url);
        $school_preview = add_query_arg(['as' => 'school'], $portal_url);
        $candidate_reg_page = get_page_by_title('Candidate Registration');
        $school_reg_page = get_page_by_title('School Registration');
        $candidate_reg_url = $candidate_reg_page ? get_permalink($candidate_reg_page) : home_url('/candidate-registration');
        $school_reg_url = $school_reg_page ? get_permalink($school_reg_page) : home_url('/school-registration');
        $candidate_admin_url = admin_url('post-new.php?post_type=cmn_candidate');
        $school_admin_url = admin_url('post-new.php?post_type=cmn_school');
        $upload_limit_warning = $this->get_candidate_doc_host_limit_warning();
        $converter_msg = isset($_GET['cmn_converter_msg']) ? sanitize_text_field(wp_unslash((string) $_GET['cmn_converter_msg'])) : '';
        $converter_url_setting = (string) get_option('cmn_cv_converter_url', '');
        if ($converter_url_setting === '') {
            $converter_url_setting = home_url('/cv-converter/');
        }
        $marketing_runner_msg = isset($_GET['cmn_marketing_runner_msg']) ? sanitize_text_field(wp_unslash((string) $_GET['cmn_marketing_runner_msg'])) : '';
        $marketing_runner_token = $this->get_marketing_runner_token();
        $marketing_runner_url = $this->build_marketing_runner_url($marketing_runner_token);
        $can_edit_release_version = $this->is_admin_user();
        $release_version = $this->get_release_version();
        $release_status = sanitize_key((string) ($_GET['cmn_release_version_status'] ?? ''));
        $release_msg = sanitize_text_field(wp_unslash((string) ($_GET['cmn_release_version_msg'] ?? '')));
        $release_standardized_notice = (string) get_option('cmn_release_version_standardized_notice', '') === '1';

        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2>Settings</h2>
            <p>Personal colour scheme and admin tools.</p>
        </header>
        <div class="cmn-portal-grid">
            <div class="cmn-dashboard-card" data-theme-settings>
                <h3>Colour Scheme</h3>
                <p class="cmn-muted">Choose how the portal looks for your account.</p>
                <label>Theme
                    <select name="cmn_theme_scheme" data-theme-select>
                        <?php foreach ($this->get_theme_scheme_choices() as $key => $label) : ?>
                            <option value="<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></option>
                        <?php endforeach; ?>
                    </select>
                </label>
                <div class="cmn-settings-actions">
                    <button class="cmn-primary" type="button" data-theme-save>Save scheme</button>
                    <span class="cmn-muted" data-theme-message></span>
                </div>
            </div>
            <div class="cmn-dashboard-card">
                <h3>Release Version</h3>
                <?php if ($release_standardized_notice && $can_edit_release_version) : ?>
                    <p class="cmn-register-success">Portal version source standardized to Release Version.</p>
                <?php endif; ?>
                <?php if ($release_msg !== '') : ?>
                    <p class="<?php echo $release_status === 'success' ? 'cmn-register-success' : 'cmn-register-error'; ?>"><?php echo esc_html($release_msg); ?></p>
                <?php endif; ?>
                <form class="cmn-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                    <?php wp_nonce_field('cmn_save_release_version', 'cmn_save_release_version_nonce'); ?>
                    <input type="hidden" name="action" value="cmn_save_release_version">
                    <input type="hidden" name="cmn_redirect" value="<?php echo esc_url(add_query_arg(['view' => 'settings'], $this->get_portal_base_url())); ?>">
                    <label>Version
                        <input type="text" name="cmn_release_version" value="<?php echo esc_attr($release_version); ?>" pattern="\d+\.\d+\.\d+"<?php echo $can_edit_release_version ? '' : ' readonly'; ?>>
                    </label>
                    <p class="cmn-muted">Set this to your latest git tag (e.g. v0.0.2).</p>
                    <?php if ($can_edit_release_version) : ?>
                        <button class="cmn-primary" type="submit">Save Version</button>
                    <?php else : ?>
                        <p class="cmn-muted">Admin only.</p>
                    <?php endif; ?>
                </form>
            </div>
            <?php if ($can_manage_admin_tools) : ?>
            <?php if ($upload_limit_warning !== '') : ?>
            <div class="cmn-dashboard-card">
                <h3>Upload Limit Warning</h3>
                <p><?php echo esc_html($upload_limit_warning); ?></p>
            </div>
            <?php endif; ?>
            <div class="cmn-dashboard-card">
                <h3>Preview Dashboards</h3>
                <p>View the portal as a candidate or school.</p>
                <div class="cmn-actions-grid">
                    <a class="cmn-primary cmn-button-link" href="<?php echo esc_url($candidate_preview); ?>">View as Candidate</a>
                    <a class="cmn-ghost" href="<?php echo esc_url($school_preview); ?>">View as School</a>
