        echo '<table class="widefat striped cmn-table">';
        echo '<thead><tr>';
        echo '<th>School</th>';
        echo '<th>Location</th>';
        echo '<th>Phone</th>';
        echo '<th>Email</th>';
        echo '<th>Contact 1</th>';
        echo '<th>Status</th>';
        echo '<th>Actions</th>';
        echo '</tr></thead><tbody>';

        if ($query->have_posts()) {
            while ($query->have_posts()) {
                $query->the_post();
                $post_id = get_the_ID();
                $edit_link = get_edit_post_link($post_id);
