        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_complete_activity_nonce']) || !wp_verify_nonce($_POST['cmn_complete_activity_nonce'], 'cmn_complete_activity')) {
