    private function read_csv_headers($file) {
        $handle = fopen($file, 'r');
        if (!$handle) {
            return [];
        }
        $header = fgetcsv($handle);
        fclose($handle);
        if (!$header) {
            return [];
        }
        return array_map('trim', $header);
    }

    private function read_spreadsheet_headers($file, $ext) {
        $ext = strtolower($ext);
        if ($ext === 'xlsx') {
            $rows = $this->read_xlsx_rows($file);
            if (!$rows) {
                return [];
            }
            $header = $rows[0] ?? [];
            return array_map('trim', array_map('strval', $header));
        }
        return $this->read_csv_headers($file);
    }

    private function read_spreadsheet_rows($file, $ext) {
        $ext = strtolower($ext);
        if ($ext === 'xlsx') {
            return $this->read_xlsx_rows($file);
        }
        return $this->read_csv_rows($file);
    }

    private function read_csv_rows($file) {
        $handle = fopen($file, 'r');
        if (!$handle) {
            return [];
        }
        $rows = [];
        while (($row = fgetcsv($handle)) !== false) {
            $rows[] = $row;
        }
        fclose($handle);
        return $rows;
    }

    private function read_xlsx_rows($file) {
        if (!class_exists('ZipArchive')) {
            return [];
        }
        $zip = new ZipArchive();
        if ($zip->open($file) !== true) {
            return [];
        }
        $shared = $this->read_xlsx_shared_strings($zip);
        $sheetXml = $this->read_xlsx_sheet_xml($zip);
        if (!$sheetXml) {
            $zip->close();
            return [];
        }
        $xml = simplexml_load_string($sheetXml);
        if (!$xml || !isset($xml->sheetData)) {
            $zip->close();
            return [];
        }
        $rows = [];
        foreach ($xml->sheetData->row as $row) {
            $cells = [];
            foreach ($row->c as $c) {
                $ref = (string) $c['r'];
                $type = (string) $c['t'];
                $value = '';
                if ($type === 's') {
                    $idx = isset($c->v) ? (int) $c->v : -1;
                    $value = $idx >= 0 && isset($shared[$idx]) ? $shared[$idx] : '';
                } elseif ($type === 'inlineStr') {
                    $value = isset($c->is->t) ? (string) $c->is->t : '';
                } else {
                    $value = isset($c->v) ? (string) $c->v : '';
                }
                $colIndex = $this->xlsx_col_to_index($ref);
                if ($colIndex !== null) {
                    $cells[$colIndex] = $value;
                }
            }
            if (!$cells) {
                $rows[] = [];
                continue;
            }
            $maxIndex = max(array_keys($cells));
            $rowData = [];
            for ($i = 0; $i <= $maxIndex; $i++) {
                $rowData[$i] = $cells[$i] ?? '';
            }
            $rows[] = $rowData;
        }
        $zip->close();
        return $rows;
    }

    private function read_xlsx_shared_strings($zip) {
        $strings = [];
        $sharedXml = $zip->getFromName('xl/sharedStrings.xml');
        if (!$sharedXml) {
            return $strings;
        }
        $xml = simplexml_load_string($sharedXml);
        if (!$xml) {
            return $strings;
        }
        foreach ($xml->si as $si) {
            $text = '';
            if (isset($si->t)) {
                $text = (string) $si->t;
            } else {
                foreach ($si->r as $r) {
                    $text .= (string) $r->t;
                }
            }
            $strings[] = $text;
        }
        return $strings;
    }

    private function read_xlsx_sheet_xml($zip) {
        $sheetXml = $zip->getFromName('xl/worksheets/sheet1.xml');
        if ($sheetXml) {
            return $sheetXml;
        }
        for ($i = 1; $i <= 5; $i++) {
            $name = 'xl/worksheets/sheet' . $i . '.xml';
            $sheetXml = $zip->getFromName($name);
            if ($sheetXml) {
                return $sheetXml;
            }
        }
        return '';
    }

    private function xlsx_col_to_index($ref) {
        if (!preg_match('/^([A-Z]+)/i', $ref, $match)) {
            return null;
        }
        $letters = strtoupper($match[1]);
        $index = 0;
        $len = strlen($letters);
        for ($i = 0; $i < $len; $i++) {
            $index = $index * 26 + (ord($letters[$i]) - 64);
        }
        return $index - 1;
    }

    private function csv_value($row, $index) {
        if ($index === '' || $index === null) {
            return '';
        }
        $idx = (int) $index;
        return isset($row[$idx]) ? trim((string) $row[$idx]) : '';
    }

    private function import_schools_spreadsheet_mapped($file, $map, $ext) {
        $rows = $this->read_spreadsheet_rows($file, $ext);
        if (!$rows) {
            return 'No rows found.';
        }
        $header = array_shift($rows);
        if (!$header) {
            return 'Empty spreadsheet.';
        }
        $count = 0;
        $skipped = 0;

        $created = 0;
        $updated = 0;
        $contact_warnings = 0;
        foreach ($rows as $row) {
            $school_name = $this->csv_value($row, $map['cmn_school_name'] ?? '');
            $location = $this->csv_value($row, $map['cmn_location'] ?? '');
            $phone = $this->csv_value($row, $map['cmn_phone'] ?? '');
            $school_email = $this->csv_value($row, $map['cmn_email'] ?? '');
            $cover_manager_name = $this->csv_value($row, $map['cmn_cover_manager'] ?? '');
            $cover_manager_email = $this->csv_value($row, $map['cmn_cover_manager_email'] ?? '');
            $email_name = $this->csv_value($row, $map['cmn_email_name'] ?? '');

            if ($school_name === '' || $location === '' || $phone === '' || $school_email === '' || $cover_manager_name === '' || $cover_manager_email === '' || $email_name === '') {
                $skipped += 1;
                continue;
            }
            if ($school_email && !is_email($school_email)) {
                $skipped += 1;
                continue;
            }
            if ($cover_manager_email && !is_email($cover_manager_email)) {
                $skipped += 1;
                continue;
            }
            if (strlen(preg_replace('/\\D+/', '', $phone)) < 7) {
                $skipped += 1;
                continue;
            }
            $school_domain = $this->get_email_domain($school_email);
            if ($school_domain === '') {
                $skipped += 1;
                continue;
            }

            $school_code = $this->csv_value($row, $map['cmn_school_id'] ?? '');
            if (!preg_match('/^CMN\\d+$/i', $school_code)) {
                $school_code = '';
            }
            $existing_id = 0;
            if ($school_code !== '') {
                $existing_id = $this->get_school_post_id_by_school_id($school_code);
            }
            if (!$existing_id) {
                $existing_id = $this->get_school_post_id_by_domain($school_domain);
            }
            if ($existing_id) {
                $post_id = $existing_id;
                wp_update_post([
                    'ID' => $post_id,
                    'post_title' => $school_name,
                ]);
                $updated++;
            } else {
                $post_id = wp_insert_post([
                    'post_type' => 'cmn_school',
                    'post_title' => $school_name,
                    'post_status' => 'publish',
                ]);
                if (is_wp_error($post_id)) {
                    $skipped += 1;
                    continue;
                }
                $created++;
            }
            $domain_owner = $this->get_school_post_id_by_domain($school_domain);
            if ($domain_owner && (int) $domain_owner !== (int) $post_id) {
                $skipped += 1;
                continue;
            }

            if ($school_code === '') {
                $school_code = get_post_meta($post_id, 'cmn_school_id', true);
                if ($school_code === '') {
                    $school_code = $this->generate_school_id();
                }
            }
            $meta = [
                'cmn_location' => $location,
                'cmn_phone' => $phone,
                'cmn_cover_manager' => $cover_manager_name,
                'cmn_cover_manager_email' => $cover_manager_email,
                'cmn_account_manager' => $this->csv_value($row, $map['cmn_account_manager'] ?? ''),
                'cmn_email' => $school_email,
                'cmn_email_name' => $email_name,
                'cmn_spoke_to_cm' => $this->csv_value($row, $map['cmn_spoke_to_cm'] ?? ''),
                'cmn_switchboard' => $this->csv_value($row, $map['cmn_switchboard'] ?? ''),
                'cmn_website' => $this->csv_value($row, $map['cmn_website'] ?? ''),
                'cmn_school_id' => $school_code,
                'cmn_status' => $this->csv_value($row, $map['cmn_status'] ?? '') ?: 'lead',
                'cmn_pipeline_stage' => $this->csv_value($row, $map['cmn_pipeline_stage'] ?? '') ?: 'new_lead',
                'cmn_school_email_domain' => $school_domain,
            ];
            if ($meta['cmn_status'] === 'client' && $meta['cmn_pipeline_stage'] !== 'lost') {
                $meta['cmn_pipeline_stage'] = $meta['cmn_pipeline_stage'] ?: 'won';
            }
            foreach ($meta as $key => $value) {
                update_post_meta($post_id, $key, sanitize_text_field($value));
            }
            $this->store_cover_manager_split($post_id, $cover_manager_name);
            $this->upsert_school_index($post_id);

            $contact_name = $this->csv_value($row, $map['cmn_contact_name'] ?? '');
            $contact_email = $this->csv_value($row, $map['cmn_contact_email'] ?? '');
            $contact_phone = $this->csv_value($row, $map['cmn_contact_phone'] ?? '');
            $contact_role = $this->csv_value($row, $map['cmn_contact_role'] ?? '');
            if ($contact_name !== '') {
                $contact_id = $this->create_or_update_contact([
                    'name' => $contact_name,
                    'email' => $contact_email,
                    'phone' => $contact_phone,
                    'role' => $contact_role,
                    'school_id' => $post_id,
                    'school_domain' => $school_domain,
                    'is_primary' => true,
                ]);
                if (!$contact_id) {
                    $contact_warnings++;
                } else {
                    update_post_meta($post_id, 'cmn_contact1', $contact_name);
                    update_post_meta($post_id, 'cmn_contact1_email', $contact_email);
                    update_post_meta($post_id, 'cmn_contact_role', $contact_role);
                    update_post_meta($post_id, 'cmn_primary_contact_name', $contact_name);
                    update_post_meta($post_id, 'cmn_primary_contact_email', $contact_email ?: $school_email);
                    update_post_meta($post_id, 'cmn_primary_contact_phone', $contact_phone ?: $phone);
                    update_post_meta($post_id, 'cmn_primary_contact_role', $contact_role);
                }
            }
            $count += 1;
        }
        $message = 'Imported ' . $count . ' schools (' . $created . ' new, ' . $updated . ' updated).';
        if ($skipped > 0) {
            $message .= ' Skipped ' . $skipped . ' rows with missing or invalid required fields.';
        }
        if ($contact_warnings > 0) {
            $message .= ' Contact warnings: ' . $contact_warnings . '.';
        }
        return $message;
    }

    private function import_contacts_spreadsheet_mapped($file, $map, $ext) {
        $rows = $this->read_spreadsheet_rows($file, $ext);
        if (!$rows) {
            return 'No rows found.';
        }
        $header = array_shift($rows);
        if (!$header) {
            return 'Empty spreadsheet.';
        }

        $count = 0;
        $created = 0;
        $updated = 0;
        $skipped = 0;
        $warnings = 0;

        foreach ($rows as $row) {
            $name = $this->csv_value($row, $map['cmn_contact_name'] ?? '');
            if ($name === '') {
                $skipped++;
                continue;
            }
            $email = $this->csv_value($row, $map['cmn_contact_email'] ?? '');
            $phone = $this->csv_value($row, $map['cmn_contact_phone'] ?? '');
            $role = $this->csv_value($row, $map['cmn_contact_role'] ?? '');
            if ($email && !is_email($email)) {
                $skipped++;
                $warnings++;
                continue;
            }
            $school_domain = '';
            $school_identifier = $this->csv_value($row, $map['cmn_contact_school_id'] ?? '');
            if ($school_identifier !== '') {
                $post_id = $this->get_school_post_id_by_school_id($school_identifier);
                if ($post_id) {
                    $school_domain = (string) get_post_meta($post_id, 'cmn_school_email_domain', true);
                } else {
                    $warnings++;
                }
            }
            if ($school_domain === '') {
                $school_email = $this->csv_value($row, $map['cmn_contact_school_email'] ?? '');
                if ($school_email !== '') {
                    $school_domain = $this->get_email_domain($school_email);
                    if ($school_domain === '') {
                        $warnings++;
                    }
                }
            }
            if ($school_domain === '') {
                $school_name = $this->csv_value($row, $map['cmn_contact_school_name'] ?? '');
                if ($school_name !== '') {
                    $ambiguous = false;
                    $school_domain = $this->find_school_domain_by_name($school_name, $ambiguous);
                    if ($ambiguous || $school_domain === '') {
                        $warnings++;
                        $school_domain = '';
                    }
                }
            }

            $existing_id = 0;
            if ($email) {
                $existing = get_posts([
                    'post_type' => 'cmn_contact',
                    'posts_per_page' => 1,
                    'fields' => 'ids',
                    'meta_query' => [
                        [
                            'key' => 'cmn_contact_email',
                            'value' => $email,
                        ],
                    ],
                ]);
                if ($existing) {
                    $existing_id = (int) $existing[0];
                }
            }

            $contact_id = $this->create_or_update_contact([
                'name' => $name,
                'email' => $email,
                'phone' => $phone,
                'role' => $role,
                'school_id' => 0,
            ]);
            if (!$contact_id) {
                $skipped++;
                continue;
            }
            if ($school_domain) {
                $this->link_contact_to_school($contact_id, $school_domain, true);
                $primary_post = $this->get_school_post_id_by_domain($school_domain);
                if ($primary_post) {
                    update_post_meta($contact_id, 'cmn_contact_school_id', $primary_post);
                }
            }
            if ($existing_id) {
                $updated++;
            } else {
                $created++;
            }
            $count++;
        }

        $message = 'Imported ' . $count . ' contacts (' . $created . ' new, ' . $updated . ' updated).';
        if ($skipped > 0) {
            $message .= ' Skipped ' . $skipped . ' rows with missing or invalid required fields.';
        }
        if ($warnings > 0) {
            $message .= ' Warnings: ' . $warnings . '.';
        }
        return $message;
    }

    public function school_columns($columns) {
        $new = [];
        $new['cb'] = $columns['cb'];
        $new['title'] = 'School';
        $new['cmn_location'] = 'Location';
        $new['cmn_phone'] = 'Phone';
        $new['cmn_email'] = 'Email';
        $new['cmn_status'] = 'Status';
        $new['date'] = $columns['date'];
        return $new;
    }

    public function school_column_values($column, $post_id) {
        switch ($column) {
            case 'cmn_location':
                echo esc_html(get_post_meta($post_id, 'cmn_location', true));
                break;
            case 'cmn_phone':
                echo esc_html(get_post_meta($post_id, 'cmn_phone', true));
                break;
            case 'cmn_email':
                echo esc_html(get_post_meta($post_id, 'cmn_email', true));
                break;
            case 'cmn_status':
                echo esc_html(get_post_meta($post_id, 'cmn_status', true));
                break;
        }
    }

    public function candidate_columns($columns) {
        $new = [];
        $new['cb'] = $columns['cb'];
        $new['title'] = 'Candidate';
        $new['cmn_location'] = 'Location';
        $new['cmn_phone'] = 'Phone';
        $new['cmn_email'] = 'Email';
        $new['cmn_status'] = 'Status';
        $new['date'] = $columns['date'];
        return $new;
    }

    public function candidate_column_values($column, $post_id) {
        switch ($column) {
            case 'cmn_location':
                echo esc_html(get_post_meta($post_id, 'cmn_location', true));
                break;
            case 'cmn_phone':
                echo esc_html(get_post_meta($post_id, 'cmn_phone', true));
                break;
            case 'cmn_email':
                echo esc_html(get_post_meta($post_id, 'cmn_email', true));
                break;
            case 'cmn_status':
                echo esc_html(get_post_meta($post_id, 'cmn_status', true));
                break;
        }
    }
}

class CmnAutomationEngine {
    private $plugin;
    private $wpdb;
    private $rules_table;
    private $logs_table;
    private $activities_table;
    private $notifications_table;
    private $audit_table;
    private $runtime_guard = [];
    private $current_rule = null;

    public function __construct($plugin, $args = []) {
        global $wpdb;
        $this->plugin = $plugin;
        $this->wpdb = isset($args['wpdb']) ? $args['wpdb'] : $wpdb;
        $prefix = $this->wpdb->prefix;
        $this->rules_table = $args['rules_table'] ?? ($prefix . 'cmn_automation_rules');
        $this->logs_table = $args['logs_table'] ?? ($prefix . 'cmn_automation_logs');
        $this->activities_table = $args['activities_table'] ?? ($prefix . 'cmn_activities');
        $this->notifications_table = $args['notifications_table'] ?? ($prefix . 'cmn_notifications');
        $this->audit_table = $args['audit_table'] ?? ($prefix . 'cmn_audit_log');
        $this->ensure_starter_rule_pack();
    }

    public function get_overview_counts() {
        $today_start = gmdate('Y-m-d 00:00:00');
        return [
            'active_rules' => (int) $this->wpdb->get_var("SELECT COUNT(*) FROM {$this->rules_table} WHERE status = 'active'"),
            'runs_today' => (int) $this->wpdb->get_var($this->wpdb->prepare(
                "SELECT COUNT(*) FROM {$this->logs_table} WHERE executed_at >= %s",
                $today_start
            )),
            'failures_today' => (int) $this->wpdb->get_var($this->wpdb->prepare(
                "SELECT COUNT(*) FROM {$this->logs_table} WHERE result = %s AND executed_at >= %s",
                'failed',
                $today_start
            )),
            'last_run_time' => (string) ($this->wpdb->get_var("SELECT MAX(executed_at) FROM {$this->logs_table}") ?: ''),
        ];
    }

    public function get_smoke_test_entities($trigger_event) {
        $trigger_event = sanitize_key((string) $trigger_event);
        $rows = [];
        if (in_array($trigger_event, ['lead_created', 'school_registered'], true)) {
            $school_ids = get_posts([
                'post_type' => 'cmn_school',
                'posts_per_page' => 12,
                'fields' => 'ids',
                'orderby' => 'ID',
                'order' => 'DESC',
            ]);
            foreach ((array) $school_ids as $school_id) {
                $school_id = (int) $school_id;
                $rows[] = [
                    'entity_type' => 'school',
                    'entity_id' => $school_id,
                    'label' => 'School #' . $school_id . ' - ' . (string) get_the_title($school_id),
                ];
            }
            return $rows;
        }
        if (in_array($trigger_event, ['candidate_registered', 'document_uploaded'], true)) {
            $candidate_ids = get_posts([
                'post_type' => 'cmn_candidate',
                'posts_per_page' => 12,
                'fields' => 'ids',
                'orderby' => 'ID',
                'order' => 'DESC',
            ]);
            foreach ((array) $candidate_ids as $candidate_id) {
                $candidate_id = (int) $candidate_id;
                $rows[] = [
                    'entity_type' => 'candidate',
                    'entity_id' => $candidate_id,
                    'label' => 'Candidate #' . $candidate_id . ' - ' . (string) get_the_title($candidate_id),
                ];
            }
            return $rows;
        }
        if (in_array($trigger_event, ['booking_created', 'booking_accepted', 'booking_declined', 'booking_requested'], true)) {
            $booking_ids = get_posts([
                'post_type' => 'cmn_booking',
                'posts_per_page' => 12,
                'fields' => 'ids',
                'orderby' => 'ID',
                'order' => 'DESC',
            ]);
            foreach ((array) $booking_ids as $booking_id) {
                $booking_id = (int) $booking_id;
                $rows[] = [
                    'entity_type' => 'booking',
                    'entity_id' => $booking_id,
                    'label' => 'Booking #' . $booking_id . ' - ' . (string) get_the_title($booking_id),
                ];
            }
            return $rows;
        }
        if ($trigger_event === 'support_ticket_opened') {
            $tickets = (array) $this->wpdb->get_results(
                "SELECT id, ticket_ref, subject
                 FROM {$this->wpdb->prefix}cmn_support_tickets
                 ORDER BY id DESC
                 LIMIT 12",
                ARRAY_A
            );
            foreach ($tickets as $ticket) {
                $rows[] = [
                    'entity_type' => 'support_ticket',
                    'entity_id' => (int) ($ticket['id'] ?? 0),
                    'label' => 'Ticket #' . (int) ($ticket['id'] ?? 0) . ' - ' . (string) ($ticket['ticket_ref'] ?? ''),
                ];
            }
            return $rows;
        }
        return $rows;
    }

    public function run_smoke_test($event, $entity_type, $entity_id, $send_real_emails = false) {
        $event = sanitize_key((string) $event);
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        $result = [
            'event' => $event,
            'entity_type' => $entity_type,
            'entity_id' => $entity_id,
            'dry_run' => $send_real_emails ? 0 : 1,
            'rules_matched' => [],
            'rules_skipped' => [],
            'actions_executed' => [],
            'failures' => [],
        ];
        if ($event === '' || $entity_type === '' || $entity_id < 1) {
            $result['failures'][] = ['message' => 'Invalid smoke test input.'];
            return $result;
        }

        $context = $this->plugin->build_automation_context($entity_type, $entity_id, $event, [
            'automation_meta' => ['source' => 'smoke_test', 'depth' => 0],
        ]);
        if (!$context) {
            $result['failures'][] = ['message' => 'Unable to build entity context for smoke test.'];
            return $result;
        }
        $rules = $this->get_active_rules_for_event($event);
        foreach ($rules as $rule) {
            $rule_id = (int) ($rule['id'] ?? 0);
            $rule_name = (string) ($rule['name'] ?? ('Rule #' . $rule_id));
            if (!$this->check_conditions($rule['conditions_json'] ?? '', $context)) {
                $result['rules_skipped'][] = ['rule_id' => $rule_id, 'name' => $rule_name, 'reason' => 'conditions_not_met'];
                continue;
            }
            $result['rules_matched'][] = ['rule_id' => $rule_id, 'name' => $rule_name];
            if ($send_real_emails) {
                $run = $this->evaluate_rule($rule, $context);
                $result['actions_executed'][] = ['rule_id' => $rule_id, 'result' => $run];
                if (($run['result'] ?? '') === 'failed') {
                    $result['failures'][] = ['rule_id' => $rule_id, 'message' => (string) ($run['message'] ?? 'Execution failed.')];
                }
                continue;
            }
            $actions_payload = $this->decode_json_payload($rule['actions_json'] ?? '', []);
            $actions = isset($actions_payload['actions']) && is_array($actions_payload['actions']) ? $actions_payload['actions'] : [];
            $result['actions_executed'][] = [
                'rule_id' => $rule_id,
                'dry_run' => 1,
                'actions' => $actions,
            ];
        }
        return $result;
    }

    private function get_entity_options($post_type, $entity_type) {
        $rows = get_posts([
            'post_type' => $post_type,
            'post_status' => 'publish',
            'posts_per_page' => 120,
            'orderby' => 'ID',
            'order' => 'DESC',
        ]);
        $out = [];
        foreach ((array) $rows as $row) {
            $out[] = [
                'entity_type' => $entity_type,
                'entity_id' => (int) $row->ID,
                'label' => '#' . (int) $row->ID . ' - ' . (string) $row->post_title,
            ];
        }
        return $out;
    }

    private function get_support_ticket_options() {
        $rows = (array) $this->wpdb->get_results(
            "SELECT id, ticket_ref, subject FROM {$this->wpdb->prefix}cmn_support_tickets ORDER BY id DESC LIMIT 120",
            ARRAY_A
        );
        $out = [];
        foreach ($rows as $row) {
            $out[] = [
                'entity_type' => 'support_ticket',
                'entity_id' => (int) ($row['id'] ?? 0),
                'label' => '#' . (int) ($row['id'] ?? 0) . ' - ' . (string) ($row['ticket_ref'] ?? '') . ' - ' . (string) ($row['subject'] ?? ''),
            ];
        }
        return $out;
    }

